/**
 * NGUON CAU SOLO LINH NHI cho bo soan Slow Rock — SINH BANG SCRIPT, KHONG SUA TAY:
 *
 *     python tools/slow_rock_linh_nhi.py --sinh > src/reharm/style/slowRockLinhNhiNguon.ts
 *
 * Moi nguon la MOT doan solo that (dao / giang / ket) cua mot ban ky am Linh Nhi.
 * - Slow rock (La Thu, Mot Coi): o = 6 moc don chum ba = 3 not den, dung luoi that
 *   (La Thu ghi sai 4/4, da cat lai theo pha bass). Hop am doc tay theo not tay trai.
 * - Bolero: o = o 4/4 cua sheet, hop am theo ky hieu sheet.
 * Cao do tinh theo nua cung so voi MIDI 60 + chuGoc. Not hoa my va duoi not noi da bo.
 */

export type OSR = {
  /** Do dai o nguon, not den (Dung Xa ket co mot o 6 phach). */
  d: number
  /** [phach trong o, goc so voi chu am, hau to, bass so voi chu am | null] */
  h: readonly (readonly [number, number, string, number | null])[]
  /** Tay phai: [phach trong o, truong do, cao do so voi MIDI 60+chuGoc] */
  r: readonly (readonly [number, number, readonly number[]])[]
  /** Tay trai, cung dang. */
  l: readonly (readonly [number, number, readonly number[]])[]
}

export type NguonSR = {
  id: string
  bai: string
  doan: 'intro' | 'interlude' | 'outro'
  thu: boolean
  dieu: 'slow rock' | 'bolero'
  /** Chu am ban goc, 0-11. */
  chuGoc: number
  /** So not den moi o nguon: 3 (o 6/8 slow rock) hoac 4 (o bolero). */
  oPhach: number
  o: readonly OSR[]
}

